# -*- coding: utf-8 -*-
# DOKUMENTY_12_09_V1
"""
БУМАГА С ПРАВИЛОМ СПРЕДА + ДОКУМЕНТЫ ЗА 11-12.09

Две работы разом, обе про то, чтобы написанное догнало сделанное.

 1. БУМАГА ТРЕЙДЕРА. Правило окружения («сверху два спреда, снизу
    один, по теням») я дописал уже ПОСЛЕ того, как Шеф поставил
    бумагу. В слотах лежит версия без него. Патч кладёт свежую —
    рядом должен быть `promt_pervyy_uroven.md`.

 2. `БИРЖА.md` — дописан день. За полтора дня сделано столько, что
    без записи оно потеряется: уровни, чистка ключа, новая бумага,
    окружение по теням, страница отчёта.

КУДА КЛАСТЬ: патч и `promt_pervyy_uroven.md` — в корень репы.

БЕЗОПАСНОСТЬ: .bak_doki12, идемпотентен, `--suho` не трогает диск.

    python obnovit_bumagu_i_dokumenty.py --suho
    python obnovit_bumagu_i_dokumenty.py

`шесть·проверено·до·корня`
"""
import shutil
import sys
from pathlib import Path

MARKER = "DOKUMENTY_12_09_V1"
SUHO = "--suho" in sys.argv

_REPO = Path(__file__).resolve().parent
ISTOCHNIK = _REPO / "promt_pervyy_uroven.md"
SLOTY = _REPO / "GRONDHEIM_CITY" / "Биржа" / "цеха" / "торговый_хаос" / "слоты"
BIRZHA = _REPO / "БИРЖА.md"

DEN = '''| 11-12.09 | **Разделили по уровням — и всё встало на места.** Неделю чинили взгляд трейдера словами: убирали Аллигатора, возвращали компасом, закрывали список условий, — а он каждый раз придумывал новое условие, чтобы не входить («жду пробоя хая», «цена не должна возвращаться к линиям», «разворотник в пасти сомнительный»). Слово Шефа: делаем по уровням, как у Вильямса. **Первый уровень — не потерять**, и на нём ровно три вещи: некрон (сигнал), AO (сила импульса), приседающий (напряжение). И **ведут пальцем по барам**, а не по приборам: приборы отвечают на вопрос, который уже задан глазами. Окна Profitunity (зелёный, фейд, фальшивка) отвергнуты Шефом как слабые — «три формулы ради того, что AO показывает лучше», а приседающий из них сильнейший и он у нас есть. Волны, точка ноль, три места входа, пасть и ангуляция — второй и третий уровень, ушли на полку, и в бумаге про это сказано прямо, чтобы он знал: оно есть, но не сейчас. **Бумага переписана начисто: 17 900 знаков → 6 400.** Прежняя была склеена из полутора десятков наших правок за неделю, и в ней слоями лежало то, что мы сами же отменяли. **Ключ будит только некроном:** излом, волна 1, откат и рождение точки из побудки убраны — трейдера будили словами второго уровня («излом верх 18 баров назад»), он их не знал и честно пересказывал как умел, разбирая при этом свежий бар вместо того, о котором речь. Считаются они по-прежнему. **Живое сообщение вычищено следом** — там до сих пор стояло «отвечай ключами brut_action» и «не входишь — verdict REJECTED», то есть отменённый ещё 10.09 путь через json: бумага говорила одно, сообщение другое, и трейдер делал по ближнему. **Окружение по теням:** трейдер называл цену и стоп на глаз (сорок пунктов, взятых ниоткуда) — края разворотного бара ему никто не давал, а формула некрона отдаёт только один край. Теперь края и обе цены даются готовыми числами, по правилу Шефа: сверху бара два спреда, снизу один, неважно, заявка это или стоп (покупка идёт по Ask — сверху платишь дважды). Спред 2 пункта, как при подготовке данных. **Второй вход закрыт рукой:** 12.09 трейдер вошёл четыре раза подряд в одно место — его будили «заявка висит», а он разбирал график заново и честно входил по правилу «сошлись — окружай». Теперь он видит, что у него уже есть, а рука ENTER при живой заявке не принимает; долив остался приказом ADD. **Возврат домой:** сходил посмотреть чужой этаж — город сам возвращает рабочий кадр, чтобы решение принималось дома («зачем по разным обрывкам работать»). Остаётся на другом, только если сменил рабочий этаж. **Страница отчёта** — кнопка в кабинете, лента карточек: кадр того бара и его разбор целиком, итог внизу, прогоны выпадающим списком. В консоли и в папках никто разбираться не будет. **Кадр к ключу:** панель меняется раз за побудку, а не на каждую служебную отрисовку. Починено попутно: подпись места врала на бар вперёд (дата кандидата вместо бара города — из-за этого казалось, что кадр отстаёт, а кадр был прав); курсор истории ставился на НАЧАЛО бара, и город не видел сам бар события — трейдера будили до того, как некрон сформировался, отсюда его вечное «жду ещё бар»; кнопка СТОП стала двухступенчатой (второе нажатие бросает, не дожидаясь ответа модели); Аллигатор убран с кадра трейдера совсем — три попытки запретить его бумагой провалились, он возвращался в каждом отказе. Остаётся: W1 не приходит (компас пуст на каждом баре, диагностика собрана), демо-счёт, вахта на другом этаже, уровни как механизм |
'''


def main():
    print()
    print("БУМАГА И ДОКУМЕНТЫ" + ("  · СУХОЙ ПРОГОН" if SUHO else ""))
    print("корень:", _REPO)
    print()

    print("1. БУМАГА ТРЕЙДЕРА (свежая, с правилом спреда):")
    if not ISTOCHNIK.exists():
        print("  !! рядом нет promt_pervyy_uroven.md")
    elif "два спреда" not in ISTOCHNIK.read_text(encoding="utf-8"):
        print("  !! в файле бумаги нет правила спреда — это старая версия")
    elif not SLOTY.exists():
        print("  !! слотов нет")
    else:
        novyy = ISTOCHNIK.read_text(encoding="utf-8")
        for slot in ("A06", "A07", "A08"):
            p = SLOTY / slot / "промпт.md"
            if p.exists() and "два спреда" in p.read_text(
                    encoding="utf-8", errors="ignore"):
                print(f"  {slot}: уже свежая")
                continue
            if not SUHO:
                if p.exists():
                    shutil.copy2(p, p.with_suffix(".md.bak_doki12"))
                p.parent.mkdir(parents=True, exist_ok=True)
                p.write_text(novyy, encoding="utf-8")
            print(f"  {slot}: {'обновится' if SUHO else 'обновлена'}")

    print()
    print("2. БИРЖА.md — дописан день:")
    if not BIRZHA.exists():
        print("  файла нет")
    else:
        txt = BIRZHA.read_text(encoding="utf-8")
        if MARKER in txt:
            print("  уже стоит")
        else:
            stroki = txt.splitlines()
            posl = max((i for i, s in enumerate(stroki)
                        if s.startswith("| ")), default=-1)
            if posl < 0:
                print("  ОТКАЗ — таблицы дней не нашёл")
            else:
                stroki.insert(posl + 1, DEN.rstrip("\n"))
                novy = "\n".join(stroki).rstrip("\n") + \
                    f"\n\n<!-- {MARKER} -->\n"
                if not SUHO:
                    shutil.copy2(BIRZHA,
                                 BIRZHA.with_suffix(".md.bak_doki12"))
                    BIRZHA.write_text(novy, encoding="utf-8")
                print(f"  {'встанет' if SUHO else 'вписано'} в таблицу "
                      f"после строки {posl + 1}")

    print()
    if SUHO:
        print("Сухой прогон: на диске ничего не изменилось.")
    else:
        print("Готово. Бэкапы — .bak_doki12")
    print()


if __name__ == "__main__":
    main()
